# ---- thermal ----
"""TN160 telemetry30 UART input. Protocol derived from Sipeed MaixPy (Apache-2.0).

See THIRD_PARTY.md. This is not the legacy 19201-byte or USB/UVC protocol.
"""
import struct
import threading


def valid_body(body):
    if len(body) != BODY_SIZE:
        return False
    vtemp, lo, hi = struct.unpack_from(">Hhh", body, PIXELS)
    if vtemp & 0xC000:
        return False
    if lo == hi == 32767:
        return True
    return -1000 <= lo <= hi <= 3200


def decode_body(body, received_at):
    vtemp, lo, hi = struct.unpack_from(">Hhh", body, PIXELS)
    return {
        "pixels": np.frombuffer(body[:PIXELS], np.uint8).reshape(THERMAL_H, THERMAL_W),
        "lo": lo, "hi": hi, "vtemp": vtemp & 0x3FFF,
        "telemetry": body[PIXELS:], "received_at": received_at,
        "valid_temperature": lo != 32767 and hi != 32767 and hi > lo,
    }


class ThermalParser:
    """Bounded incremental parser; acquire sync using two consecutive plausible frames.

    Once locked, accepts a complete frame without throwing it away just because
    noise follows it. There is no firmware CRC; false sync is still possible.
    """
    def __init__(self, skip=10):
        self.buffer = bytearray()
        self.locked = False
        self.skip = skip
        self.frames = 0
        self.output_frames = 0
        self.discarded_bytes = 0

    def feed(self, chunk, received_at=None):
        now = time.monotonic() if received_at is None else received_at
        self.buffer.extend(chunk)
        latest = None
        while True:
            idx = self.buffer.find(b"\xff")
            if idx < 0:
                self.discarded_bytes += len(self.buffer)
                self.buffer.clear()
                self.locked = False
                break
            if idx:
                self.discarded_bytes += idx
                del self.buffer[:idx]
                self.locked = False
            if len(self.buffer) < WIRE_SIZE:
                break
            body = bytes(self.buffer[1:WIRE_SIZE])
            if not valid_body(body):
                del self.buffer[0]
                self.discarded_bytes += 1
                self.locked = False
                continue
            if not self.locked:
                if len(self.buffer) < WIRE_SIZE * 2:
                    break
                next_body = bytes(self.buffer[WIRE_SIZE + 1:WIRE_SIZE * 2])
                if self.buffer[WIRE_SIZE] != 255 or not valid_body(next_body):
                    del self.buffer[0]
                    self.discarded_bytes += 1
                    continue
                self.locked = True
            del self.buffer[:WIRE_SIZE]
            self.frames += 1
            if self.skip > 0:
                self.skip -= 1
            else:
                self.output_frames += 1
                latest = decode_body(body, now)
            # A frame may end exactly at the read boundary; retain the sync state.
            if not self.buffer:
                break
        return latest


class ThermalReader:
    """One UART owner thread, latest-frame mailbox, finite reads and reconnection."""
    def __init__(self, config):
        self.config = config
        self.stop_event = threading.Event()
        self.lock = threading.Lock()
        self.latest = None
        self.status = "THERMAL STARTING"
        self.total_frames = 0
        self.reset_gpio = None
        self.thread = threading.Thread(target=self._run, name="thermal-uart", daemon=True)

    def start(self):
        self.thread.start()

    def snapshot(self):
        with self.lock:
            return self.latest, self.status, self.total_frames

    def _status(self, message, clear=False):
        with self.lock:
            self.status = message
            if clear:
                self.latest = None

    def _open(self):
        from maix import gpio, pinmap, err
        from maix.peripheral import uart
        c = self.config
        if c["configure_uart_pins"]:
            for pin, function in (("B0", "UART2_TX"), ("B1", "UART2_RX")):
                err.check_raise(pinmap.set_pin_function(pin, function), "UART2 pinmap: " + pin)
        err.check_raise(pinmap.set_pin_function(c["reset_pin"], c["reset_gpio"]), "Thermal reset pinmap")
        self.reset_gpio = gpio.GPIO(c["reset_gpio"], gpio.Mode.OUT)
        idle = 1 - c["reset_active"]
        self.reset_gpio.value(idle)
        time.sleep(0.02)
        self.reset_gpio.value(c["reset_active"])
        time.sleep(0.12)
        self.reset_gpio.value(idle)
        time.sleep(0.40)
        serial = uart.UART(port=c["uart_port"], baudrate=2000000)
        try:
            serial.write(b"\x44")
        finally:
            serial.close()
        time.sleep(0.10)
        return uart.UART(port=c["uart_port"], baudrate=4000000)

    def _run(self):
        while not self.stop_event.is_set():
            serial = None
            try:
                self._status("THERMAL CONNECTING", clear=True)
                LOG.info("THERMAL opening %s / telemetry30", self.config["uart_port"])
                serial = self._open()
                LOG.info("THERMAL UART ready; waiting for valid frames")
                parser = ThermalParser(self.config["skip_frames"])
                last_valid = time.monotonic()
                while not self.stop_event.is_set():
                    try:
                        chunk = serial.read(32768, timeout=2)
                    except TypeError:
                        chunk = serial.read(32768, 2)
                    if chunk:
                        before = parser.output_frames
                        frame = parser.feed(bytes(chunk))
                        if frame is not None:
                            if before == 0:
                                LOG.info("THERMAL first frame received; temperature_valid=%s", frame["valid_temperature"])
                            last_valid = time.monotonic()
                            with self.lock:
                                self.latest = frame
                                self.status = "THERMAL OK" if frame["valid_temperature"] else "UNCALIBRATED"
                                self.total_frames += parser.output_frames - before
                    else:
                        self.stop_event.wait(0.001)
                    if time.monotonic() - last_valid > self.config["thermal_retry_seconds"]:
                        raise RuntimeError("No telemetry30 frames; check module firmware/wiring")
            except Exception as exc:
                LOG.warning("Thermal input: %s", exc)
                self._status("THERMAL OFFLINE / CHECK FIRMWARE", clear=True)
            finally:
                if serial is not None:
                    try:
                        serial.close()
                    except Exception:
                        LOG.exception("UART close failed")
            self.stop_event.wait(1.0)

    def close(self):
        self.stop_event.set()
        if self.thread.is_alive():
            self.thread.join(timeout=3.0)
        if self.thread.is_alive():
            LOG.warning("UART thread did not exit within 3 seconds")


# ---- calibration ----
"""Planar cross-spectrum registration and full-screen paired-point calibration.

Matrices map RAW (unflipped) thermal pixels to RGB camera-input pixels.
Each distance is measured independently. No depth estimation or matrix interpolation.
"""


def distance_key(distance):
    value = float(distance)
    if not np.isfinite(value) or value <= 0:
        raise ValueError("Calibration distance must be positive metres")
    return "%gm" % value


def validate_homography(matrix, source_size):
    h = np.asarray(matrix, np.float64)
    if h.shape != (3, 3) or not np.isfinite(h).all() or abs(h[2, 2]) < 1e-9:
        raise ValueError("Invalid registration matrix")
    h = h / h[2, 2]
    if abs(np.linalg.det(h)) < 1e-9 or np.linalg.cond(h) > 1e9:
        raise ValueError("Singular registration matrix")
    corners = np.array([[0, 0], [159, 0], [159, 119], [0, 119]], np.float64)
    denom = np.c_[corners, np.ones(4)] @ h[2]
    if np.min(denom) <= 1e-5:
        raise ValueError("Perspective horizon crosses the thermal image")
    mapped = cv2.perspectiveTransform(corners.reshape(-1, 1, 2), h).reshape(-1, 2)
    if np.any(np.abs(mapped) > max(source_size) * 20):
        raise ValueError("Registration extrapolates too far")
    area = abs(cv2.contourArea(mapped.astype(np.float32)))
    if area < 4 or area > np.prod(source_size) * 100:
        raise ValueError("Invalid projected thermal area")
    return h


def calibration_points(points, size, minimum):
    pts = np.asarray(points, np.float64)
    if pts.ndim != 2 or pts.shape[1] != 2 or len(pts) < minimum or not np.isfinite(pts).all():
        raise ValueError("Need at least %d complete finite point pairs" % minimum)
    if np.any(pts < 0) or np.any(pts > np.asarray(size) - 1):
        raise ValueError("Calibration point outside its source image")
    if len(np.unique(pts, axis=0)) != len(pts):
        raise ValueError("Repeated point: choose distinct markers")
    return pts


def point_errors(matrix, thermal_points, visible_points):
    predicted = cv2.perspectiveTransform(np.asarray(thermal_points, np.float64).reshape(-1, 1, 2), matrix).reshape(-1, 2)
    return np.linalg.norm(predicted - np.asarray(visible_points), axis=1)


def fit_registration(thermal_points, visible_points, source_size, threshold=4.0):
    src = calibration_points(thermal_points, (THERMAL_W, THERMAL_H), 6)
    dst = calibration_points(visible_points, source_size, 6)
    if len(src) != len(dst):
        raise ValueError("Point-pair counts differ")
    def coverage(points, size):
        return abs(cv2.contourArea(cv2.convexHull(points.astype(np.float32)))) / np.prod(size)
    if coverage(src, (THERMAL_W, THERMAL_H)) < .03 or coverage(dst, source_size) < .02:
        raise ValueError("Spread markers across the shared field; points too narrow/collinear")
    matrix, mask = cv2.findHomography(src, dst, cv2.RANSAC, float(threshold))
    if matrix is None or mask is None:
        raise ValueError("Cannot solve registration")
    inliers = mask.ravel().astype(bool)
    if inliers.sum() < max(6, int(np.ceil(len(src) * .75))):
        raise ValueError("Too many mismatched markers; undo and repick")
    if coverage(src[inliers], (THERMAL_W, THERMAL_H)) < .03 or coverage(dst[inliers], source_size) < .02:
        raise ValueError("Valid pairs do not cover enough of the shared field")
    matrix = validate_homography(matrix, source_size)
    errors = point_errors(matrix, src, dst)
    return matrix, {"pairs": len(src), "inliers": int(inliers.sum()),
                    "fit_rmse_px": float(np.sqrt(np.mean(errors[inliers] ** 2))),
                    "rejected_indices": np.flatnonzero(~inliers).tolist(),
                    "thermal_points": src.tolist(), "visible_points": dst.tolist()}


def check_registration(matrix, thermal_points, visible_points, source_size, fit, maximum=6.0):
    src = calibration_points(thermal_points, (THERMAL_W, THERMAL_H), 2)
    dst = calibration_points(visible_points, source_size, 2)
    if len(src) != len(dst):
        raise ValueError("Check-pair counts differ")
    for new, old, separation in ((src, fit["thermal_points"], 2), (dst, fit["visible_points"], 3)):
        distances = np.linalg.norm(new[:, None, :] - np.asarray(old)[None, :, :], axis=2)
        if distances.min() < separation:
            raise ValueError("Check on NEW markers, not the fitting markers")
    if np.max(np.linalg.norm(src - src[0], axis=1)) < 10:
        raise ValueError("Spread the independent check markers apart")
    errors = point_errors(validate_homography(matrix, source_size), src, dst)
    if errors.max() > maximum:
        raise ValueError("Check error %.1fpx > %.1fpx; repick/recalibrate" % (errors.max(), maximum))
    return {"check_pairs": len(src), "check_rmse_px": float(np.sqrt(np.mean(errors ** 2))),
            "check_max_px": float(errors.max()), "check_thermal_points": src.tolist(),
            "check_visible_points": dst.tolist()}


class CalibrationSession:
    def __init__(self, alignment):
        self.alignment = alignment
        self.active = False
        self.latest = None
        self.reset()

    def reset(self):
        self.frozen = None
        self.pending = None
        self.thermal_points, self.visible_points = [], []
        self.check_thermal, self.check_visible = [], []
        self.candidate, self.fit = None, None
        self.phase = "FIT"
        self.message = "Keep a flat target still at selected distance; FREEZE"

    def begin(self):
        self.reset()
        self.active = True

    def observe(self, rgb, thermal, visible_at, now):
        self.latest = (rgb, thermal, visible_at)

    def freeze(self):
        if self.latest is None:
            raise ValueError("Wait for both cameras")
        rgb, thermal, visible_at = self.latest
        state, show, _ = thermal_state(thermal, visible_at, time.monotonic(), self.alignment.config)
        if not show:
            raise ValueError("Cannot freeze: " + state)
        frozen = (rgb.copy(), dict(thermal, pixels=thermal["pixels"].copy()))
        self.reset()
        self.frozen = frozen
        self.message = "Tap RGB marker, then SAME marker in thermal; repeat 6-12 pairs"

    def controls(self):
        width = self.alignment.config["width"]
        names = ["CANCEL", "FREEZE", "UNDO", "FIT", "APPLY"]
        return [(name, (i * width // 5, 0, width // 5, 34)) for i, name in enumerate(names)]

    def panel(self, thermal_view):
        c = self.alignment.config
        sw, sh = (THERMAL_W, THERMAL_H) if thermal_view else self.alignment.source_size
        x, y, w, h, _, _ = letterbox_geometry(sw, sh, c["width"], c["height"] - 140)
        return x, y + 84, w, h, sw, sh

    def panel_point(self, x, y, thermal_view):
        bx, by, w, h, sw, sh = self.panel(thermal_view)
        if not (bx <= x < bx + w and by <= y < by + h):
            return None
        px = float(np.clip((x - bx + .5) * sw / w - .5, 0, sw - 1))
        py = float(np.clip((y - by + .5) * sh / h - .5, 0, sh - 1))
        c = self.alignment.config
        if thermal_view:
            px = sw - 1 - px if c["thermal_flip_x"] else px
            py = sh - 1 - py if c["thermal_flip_y"] else py
        return [float(px), float(py)]

    def screen_point(self, point, thermal_view):
        bx, by, w, h, sw, sh = self.panel(thermal_view)
        px, py = point
        c = self.alignment.config
        if thermal_view:
            px = sw - 1 - px if c["thermal_flip_x"] else px
            py = sh - 1 - py if c["thermal_flip_y"] else py
        return int(round(bx + (px + .5) * w / sw - .5)), int(round(by + (py + .5) * h / sh - .5))

    def action(self, name):
        if name == "CANCEL":
            self.active = False
        elif name == "FREEZE":
            self.freeze()
        elif name == "UNDO":
            src, dst = self.current_points()
            if self.pending is not None:
                self.pending = None
            elif src:
                src.pop()
                dst.pop()
            self.message = "Last selection undone"
        elif name == "FIT":
            if self.pending is not None:
                raise ValueError("Finish or UNDO the current pair")
            self.candidate, self.fit = fit_registration(self.thermal_points, self.visible_points,
                self.alignment.source_size, self.alignment.config["calibration_ransac_px"])
            self.phase = "CHECK"
            self.check_thermal, self.check_visible = [], []
            self.message = "Fit %.1fpx; select 2+ NEW check pairs, then APPLY" % self.fit["fit_rmse_px"]
        elif name == "APPLY":
            if self.candidate is None or self.pending is not None:
                raise ValueError("FIT first, then finish 2+ independent check pairs")
            stats = check_registration(self.candidate, self.check_thermal, self.check_visible,
                self.alignment.source_size, self.fit, self.alignment.config["calibration_max_error_px"])
            self.alignment.set_registration(self.candidate, dict(self.fit, **stats))
            self.active = False
            # Applying is live; SAVE persists all distance profiles separately.
            self.message = "Applied at %s; press SAVE to persist" % distance_key(self.alignment.distance)

    def current_points(self):
        return (self.thermal_points, self.visible_points) if self.phase == "FIT" else (self.check_thermal, self.check_visible)

    def click(self, x, y):
        try:
            for name, (bx, by, w, h) in self.controls():
                if bx <= x < bx + w and by <= y < by + h:
                    self.action(name)
                    return
            if self.frozen is None:
                return
            thermal_view = self.pending is not None
            point = self.panel_point(x, y, thermal_view)
            if point is None:
                return
            if not thermal_view:
                self.pending = point
            else:
                src, dst = self.current_points()
                if len(src) >= 24:
                    raise ValueError("Maximum 24 pairs; FIT or APPLY")
                src.append(point)
                dst.append(self.pending)
                self.pending = None
            count = len(self.current_points()[0])
            self.message = "%s pairs: %d; tap %s" % (self.phase, count, "THERMAL" if self.pending else "RGB")
        except Exception as exc:
            self.message = str(exc)
            LOG.warning("Calibration: %s", exc)

    def render(self):
        c = self.alignment.config
        canvas = np.full((c["height"], c["width"], 3), 18, np.uint8)
        thermal_view = self.pending is not None
        data = self.frozen or (self.latest[:2] if self.latest else None)
        if data is not None:
            rgb, thermal = data
            if thermal_view and thermal is not None:
                pixels = thermal["pixels"]
                if c["thermal_flip_x"]:
                    pixels = pixels[:, ::-1]
                if c["thermal_flip_y"]:
                    pixels = pixels[::-1, :]
                pixels = cv2.cvtColor(cv2.applyColorMap(np.ascontiguousarray(pixels), cv2.COLORMAP_JET), cv2.COLOR_BGR2RGB)
            else:
                pixels = rgb
            x, y, w, h, _, _ = self.panel(thermal_view)
            canvas[y:y + h, x:x + w] = cv2.resize(pixels, (w, h))
            src, dst = self.current_points()
            for i, point in enumerate(src if thermal_view else dst):
                px, py = self.screen_point(point, thermal_view)
                cv2.drawMarker(canvas, (px, py), (80, 255, 80), cv2.MARKER_CROSS, 10, 1)
                draw_text_rgb(canvas, str(i + 1), px + 5, py - 5, scale=.4)
        for name, (x, y, w, h) in self.controls():
            cv2.rectangle(canvas, (x, y), (x + w - 2, y + h - 2), (35, 40, 55), -1)
            draw_text_rgb(canvas, name, x + 6, y + 23, scale=.48)
        title = "%s | %s | %s | %s" % (distance_key(self.alignment.distance),
            "THERMAL" if thermal_view else "RGB", self.phase, "FROZEN" if self.frozen else "LIVE")
        draw_text_rgb(canvas, title, 8, 57, (255, 220, 80), .55)
        # Split long messages so failures remain readable at the default 640px output.
        draw_text_rgb(canvas, self.message[:78], 6, c["height"] - 30, scale=.42)
        draw_text_rgb(canvas, self.message[78:156], 6, c["height"] - 10, scale=.42)
        return canvas


# ---- fusion ----
"""Geometry, raw-pixel ROI thermometry and shared screen/RTSP composition."""
import json


def letterbox_geometry(source_w, source_h, output_w, output_h):
    scale = min(output_w / source_w, output_h / source_h)
    width, height = round(source_w * scale), round(source_h * scale)
    return ((output_w - width) // 2, (output_h - height) // 2,
            width, height, width / source_w, height / source_h)


class Alignment:
    def __init__(self, config, source_size, path=None):
        self.config, self.source_size, self.path = config, tuple(source_size), path
        self.rect = list(config["thermal_rect"])
        self.manual = False
        self.homography = None
        self.registration_stats = {}
        self.distances = [float(d) for d in config["calibration_distances_m"]]
        if not self.distances or len(set(self.distances)) != len(self.distances):
            raise ValueError("Calibration distances must be nonempty and unique")
        for d in self.distances:
            distance_key(d)
        self.distance = float(config["calibration_distance_m"])
        if self.distance not in self.distances:
            raise ValueError("Active calibration distance must be a configured slot")
        self.profiles = {}
        self.adjustments = {}
        self.tuning = [1.0, 1.0, 0.0, 0.0]  # scale X/Y, shift as RGB viewport fractions
        self.load_profiles(config.get("calibration_profiles", {}))
        self.load_adjustments(config.get("manual_adjustments", {}))
        if path and os.path.isfile(path):
            try:
                with open(path, encoding="utf-8") as handle:
                    saved = json.load(handle)
                rect = saved["rect"]
                if saved.get("source_size") != list(source_size):
                    raise ValueError("Camera/model resolution changed; realign")
                if saved.get("camera_fps") != config["camera_fps"]:
                    raise ValueError("Camera FPS/mode changed or unknown; recalibrate")
                if saved.get("flips") != [config["thermal_flip_x"], config["thermal_flip_y"]]:
                    raise ValueError("Thermal orientation changed; realign")
                if (len(rect) != 4 or not all(np.isfinite(rect)) or
                        not 0.1 <= rect[2] <= 2.0 or not 0.1 <= rect[3] <= 2.0 or
                        not -1.0 <= rect[0] <= 1.0 or not -1.0 <= rect[1] <= 1.0):
                    raise ValueError("Invalid alignment rectangle")
                self.rect = [float(v) for v in rect]
                self.manual = True
                self.load_profiles(saved.get("profiles", {}))
                self.load_adjustments(saved.get("manual_adjustments", {}))
                if saved.get("active_distance_m") in self.distances:
                    self.distance = float(saved["active_distance_m"])
            except Exception as exc:
                LOG.warning("Alignment ignored: %s", exc)
        self.select_distance(self.distance)

    def load_adjustments(self, adjustments):
        for key, record in adjustments.items():
            try:
                values = record["values"]
                if (record.get("source_size") != list(self.source_size) or
                        record.get("camera_fps") != self.config["camera_fps"] or
                        record.get("flips") != [self.config["thermal_flip_x"], self.config["thermal_flip_y"]] or
                        len(values) != 4 or not np.isfinite(values).all() or
                        not all(.1 <= v <= 4 for v in values[:2]) or
                        not all(-2 <= v <= 2 for v in values[2:])):
                    raise ValueError("Invalid manual scale/shift or changed camera geometry")
                self.adjustments[key] = dict(record, values=[float(v) for v in values])
            except Exception as exc:
                LOG.warning("Ignoring manual adjustment %s: %s", key, exc)

    @property
    def manually_tuned(self):
        return not np.allclose(self.tuning, [1, 1, 0, 0], rtol=0, atol=1e-10)

    def load_profiles(self, profiles):
        for key, profile in profiles.items():
            try:
                if (profile.get("source_size") != list(self.source_size) or
                        profile.get("camera_fps") != self.config["camera_fps"] or
                        profile.get("thermal_size") != [THERMAL_W, THERMAL_H] or
                        profile.get("flips") != [self.config["thermal_flip_x"], self.config["thermal_flip_y"]] or
                        distance_key(profile["distance_m"]) != key):
                    raise ValueError("Profile geometry/distance changed")
                validate_homography(profile["matrix"], self.source_size)
                # Recheck stored independent measurements, not just a claimed PASS flag.
                stats = check_registration(profile["matrix"], profile["check_thermal_points"],
                    profile["check_visible_points"], self.source_size, profile,
                    self.config["calibration_max_error_px"])
                self.profiles[key] = dict(profile, **stats)
            except Exception as exc:
                LOG.warning("Ignoring profile %s: %s", key, exc)

    def select_distance(self, distance):
        if float(distance) not in self.distances:
            raise ValueError("Unknown calibration distance")
        self.distance = float(distance)
        profile = self.profiles.get(distance_key(self.distance))
        self.homography = validate_homography(profile["matrix"], self.source_size) if profile else None
        self.registration_stats = profile or {}
        self.tuning = list(self.adjustments.get(distance_key(self.distance), {}).get("values", [1., 1., 0., 0.]))
        self.rebuild()

    def next_distance(self):
        self.select_distance(self.distances[(self.distances.index(self.distance) + 1) % len(self.distances)])

    def set_registration(self, matrix, stats):
        matrix = validate_homography(matrix, self.source_size)
        checks = check_registration(matrix, stats["check_thermal_points"], stats["check_visible_points"],
                                    self.source_size, stats, self.config["calibration_max_error_px"])
        profile = dict(stats, **checks)
        profile.update(matrix=matrix.tolist(), source_size=list(self.source_size),
                       camera_fps=self.config["camera_fps"],
                       thermal_size=[THERMAL_W, THERMAL_H],
                       flips=[self.config["thermal_flip_x"], self.config["thermal_flip_y"]],
                       distance_m=self.distance)
        self.profiles[distance_key(self.distance)] = profile
        # New measured geometry replaces manual edits of the old geometry.
        self.adjustments.pop(distance_key(self.distance), None)
        self.select_distance(self.distance)

    def rebuild(self):
        self._heat_frame = self._heat_image = None
        c = self.config
        x, y, w, h, sx, sy = letterbox_geometry(*self.source_size, c["width"], c["height"])
        self.viewport = (x, y, w, h, sx, sy)
        rx, ry, rw, rh = self.rect
        flip = np.eye(3, dtype=np.float32)
        if c["thermal_flip_x"]:
            flip[0, 0], flip[0, 2] = -1, THERMAL_W - 1
        if c["thermal_flip_y"]:
            flip[1, 1], flip[1, 2] = -1, THERMAL_H - 1
        target = np.array([[rw * (w - 1) / (THERMAL_W - 1), 0, x + rx * (w - 1)],
                           [0, rh * (h - 1) / (THERMAL_H - 1), y + ry * (h - 1)],
                           [0, 0, 1]], np.float32)
        self.matrix = target @ flip
        if self.homography is not None:
            # H already includes orientation; never apply the thermal flip twice.
            # Match cv2.resize's pixel-centre convention used to draw the RGB image.
            to_canvas = np.array([[sx, 0, x + (sx - 1) / 2],
                                  [0, sy, y + (sy - 1) / 2], [0, 0, 1]], np.float64)
            self.matrix = to_canvas @ self.homography
        self.base_matrix = self.matrix.copy()
        centre = np.array([[[ (THERMAL_W - 1) / 2, (THERMAL_H - 1) / 2 ]]], np.float64)
        cx, cy = cv2.perspectiveTransform(centre, self.base_matrix).reshape(2)
        zx, zy, dx, dy = self.tuning
        post = np.array([[zx, 0, cx * (1 - zx) + dx * w],
                         [0, zy, cy * (1 - zy) + dy * h], [0, 0, 1]], np.float64)
        self.matrix = post @ self.base_matrix
        self.overlay_centre = (cx + dx * w, cy + dy * h)
        yy, xx = np.indices((THERMAL_H, THERMAL_W), dtype=np.float32)
        points = np.dstack((xx, yy)).reshape(-1, 1, 2)
        mapped = cv2.perspectiveTransform(points, self.matrix).reshape(THERMAL_H, THERMAL_W, 2)
        self.mx, self.my = mapped[:, :, 0], mapped[:, :, 1]
        self.visible_samples = ((self.mx >= x) & (self.mx < x + w) &
                                (self.my >= y) & (self.my < y + h))
        mask = cv2.warpPerspective(np.full((THERMAL_H, THERMAL_W), 255, np.uint8),
                                   self.matrix, (c["width"], c["height"]), flags=cv2.INTER_NEAREST)
        viewport_mask = np.zeros_like(mask)
        viewport_mask[y:y + h, x:x + w] = 255
        self.mask = (mask > 0) & (viewport_mask > 0)
        self.outlines = cv2.findContours(self.mask.astype(np.uint8), cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)[-2]

    def heat_image(self, frame):
        if frame is not self._heat_frame:
            colored = cv2.applyColorMap(frame["pixels"], getattr(cv2, "COLORMAP_TURBO", cv2.COLORMAP_JET))
            colored = cv2.cvtColor(colored, cv2.COLOR_BGR2RGB)
            self._heat_image = cv2.warpPerspective(colored, self.matrix,
                (self.config["width"], self.config["height"]), flags=cv2.INTER_LINEAR)
            self._heat_frame = frame
        return self._heat_image

    def display_box(self, box):
        x, y, w, h, sx, sy = self.viewport
        bx, by, bw, bh = box
        left, top = max(x, x + bx * sx), max(y, y + by * sy)
        right, bottom = min(x + w, x + (bx + bw) * sx), min(y + h, y + (by + bh) * sy)
        return left, top, max(0.0, right - left), max(0.0, bottom - top)

    def adjust(self, action, fine=False):
        self.manual = False
        zoom, step = (1.01, .002) if fine else (1.05, .01)
        values = list(self.tuning)
        if action == "RESET":
            values = [1., 1., 0., 0.]
        elif action in ("NEAR", "FAR"):
            factor = zoom if action == "NEAR" else 1 / zoom
            # Joint limit preserves aspect ratio even when either axis reaches a bound.
            factor = float(np.clip(factor, max(.1 / v for v in values[:2]), min(4 / v for v in values[:2])))
            values[0] *= factor
            values[1] *= factor
        elif action in ("W-", "W+", "H-", "H+"):
            index = 0 if action[0] == "W" else 1
            values[index] = float(np.clip(values[index] * (zoom if action[1] == "+" else 1 / zoom), .1, 4))
        else:
            index, direction = {"LEFT": (2, -1), "RIGHT": (2, 1), "UP": (3, -1), "DOWN": (3, 1)}[action]
            values[index] = float(np.clip(values[index] + step * direction, -2, 2))
        self.tuning = values
        self.adjustments[distance_key(self.distance)] = {
            "values": values, "source_size": list(self.source_size),
            "camera_fps": self.config["camera_fps"],
            "flips": [self.config["thermal_flip_x"], self.config["thermal_flip_y"]]}
        self.rebuild()

    def save(self):
        if not self.path:
            raise RuntimeError("No persistent alignment path")
        saved = {"schema": 4, "rect": self.rect, "source_size": list(self.source_size),
                 "camera_fps": self.config["camera_fps"],
                 "manual_adjustments": self.adjustments,
                 "profiles": self.profiles, "active_distance_m": self.distance,
                 "flips": [self.config["thermal_flip_x"], self.config["thermal_flip_y"]]}
        os.makedirs(os.path.dirname(os.path.abspath(self.path)), exist_ok=True)
        with open(self.path + ".tmp", "w", encoding="utf-8") as handle:
            json.dump(saved, handle, indent=2)
        os.replace(self.path + ".tmp", self.path)
        self.manual = True
        LOG.info("Saved alignment at %s; CONFIG thermal_rect = %s", self.path, self.rect)
        if self.profiles:
            print("CONFIG['calibration_profiles'] = " + repr(self.profiles), flush=True)
        if self.adjustments:
            print("CONFIG['manual_adjustments'] = " + repr(self.adjustments), flush=True)


def thermal_state(frame, visible_at, now, config):
    if frame is None:
        return "NO THERMAL", False, False
    age = now - frame["received_at"]
    if age < 0 or age > config["max_thermal_age"]:
        return "THERMAL STALE", False, False
    if abs(visible_at - frame["received_at"]) > config["max_pair_delta"]:
        return "THERMAL DESYNC", False, False
    if not frame["valid_temperature"]:
        return "UNCALIBRATED", True, False
    return "THERMAL OK", True, True


def roi_temperature(frame, box, alignment):
    """Sample original thermal pixels, never interpolated/colorized pixels."""
    if frame is None or not frame["valid_temperature"]:
        return None
    x, y, w, h = box
    if w <= 0 or h <= 0:
        return None
    mask = (alignment.visible_samples & (alignment.mx >= x) & (alignment.mx < x + w) &
            (alignment.my >= y) & (alignment.my < y + h))
    values = frame["pixels"][mask]
    if values.size < 1:
        return None
    temps = frame["lo"] / 10.0 + (frame["hi"] - frame["lo"]) / 10.0 * np.minimum(values.astype(np.float32) / 254, 1.0)
    return {"max": float(temps.max()), "mean": float(temps.mean()), "samples": int(values.size)}


def draw_text_rgb(canvas, text, x, y, color=(255, 255, 255), scale=.5):
    # ASCII UI avoids an external font dependency; array channels are RGB.
    x, y = int(x), int(y)
    cv2.putText(canvas, str(text), (x + 1, y + 1), cv2.FONT_HERSHEY_SIMPLEX, scale, (0, 0, 0), 2, cv2.LINE_AA)
    cv2.putText(canvas, str(text), (x, y), cv2.FONT_HERSHEY_SIMPLEX, scale, color, 1, cv2.LINE_AA)


def compose(rgb, detections, thermal, alignment, now, visible_at, mode="FUSION", alpha=.4,
            show_temperature=True, show_overlay=True):
    c = alignment.config
    out = np.zeros((c["height"], c["width"], 3), np.uint8)
    x, y, w, h, _, _ = alignment.viewport
    out[y:y + h, x:x + w] = cv2.resize(rgb, (w, h))
    state, show_heat, use_temp = thermal_state(thermal, visible_at, now, c)
    effective_mode = mode if show_overlay else "VISIBLE"
    if effective_mode == "THERMAL":
        out[:] = 15
    if show_heat and effective_mode != "VISIBLE":
        heat = alignment.heat_image(thermal)
        blend = heat if effective_mode == "THERMAL" else cv2.addWeighted(out, 1 - alpha, heat, alpha, 0)
        out[alignment.mask] = blend[alignment.mask]
    results = []
    for det in detections[:c["max_objects"]]:
        box = alignment.display_box(det["box"])
        bx, by, bw, bh = box
        if bw <= 0 or bh <= 0:
            continue
        # Async boxes belong to an older RGB frame. Do not assign temperatures when timestamps diverge.
        pair_ok = thermal is not None and abs(det.get("captured_at", visible_at) - thermal["received_at"]) <= c["max_detection_thermal_delta"]
        result = roi_temperature(thermal, box, alignment) if show_temperature and use_temp and pair_ok else None
        results.append(result)
        cv2.rectangle(out, (int(bx), int(by)), (int(bx + bw - 1), int(by + bh - 1)), (80, 255, 80), 2)
        label = "%s %.0f%%" % (det["label"], det["score"] * 100)
        if not show_temperature:
            pass
        elif result:
            label += " ROI max ~%.1fC" % result["max"]
        else:
            label += " T:--"
        tx = int(np.clip(bx, 0, max(0, c["width"] - len(label) * 8)))
        ty = int(np.clip(by - 6, 66, c["height"] - 38))
        draw_text_rgb(out, label, tx, ty, (130, 255, 130), .45)
    global_stats = roi_temperature(thermal, (x, y, w, h), alignment) if show_temperature and use_temp else None
    detail = ("max ~%.1fC" % global_stats["max"] if global_stats else "T:--") if show_temperature else "TEMP OFF"
    if alignment.manually_tuned:
        align_text = distance_key(alignment.distance) + " MANUAL TUNE"
    elif alignment.homography is not None:
        align_text = "%s check %.1fpx" % (distance_key(alignment.distance), alignment.registration_stats["check_max_px"])
    else:
        align_text = distance_key(alignment.distance) + " NO POINT CAL"
    draw_text_rgb(out, "%s | %s | %s" % (state, detail, align_text), 8, 83, (255, 220, 80), .48)
    return out, results, state


class TouchUI:
    def __init__(self, alignment, hot_tracker=None):
        self.alignment = alignment
        self.hot_tracker = hot_tracker
        self.mode, self.alpha = "FUSION", alignment.config["alpha"]
        self.show_temperatures, self.show_heat = True, True
        self.calibrating, self.was_pressed = False, False
        self.message, self.message_until = "", 0.0
        self.registration = CalibrationSession(alignment)
        self.fine = False

    def buttons(self):
        width, height = self.alignment.config["width"], self.alignment.config["height"]
        labels = ["EXIT", "VIEW", "ALPHA", "DIST", "CAL", "ALIGN", "SAVE", "TEMP", "HEAT"]
        if self.hot_tracker is not None:
            labels.append("HOT")
        # Two generous rows keep all actions usable on the 480px-wide portrait display.
        columns = 5
        buttons = [(name, ((i % columns) * width // columns, (i // columns) * 32,
                           width // columns, 31)) for i, name in enumerate(labels)]
        if self.calibrating:
            labels = ["FAR", "NEAR", "LEFT", "RIGHT", "UP", "DOWN", "W-", "W+", "H-", "H+", "FINE", "RESET"]
            for i, name in enumerate(labels):
                buttons.append((name, ((i % 6) * width // 6, height - 106 + (i // 6) * 38, width // 6, 36)))
        return buttons

    def touch(self, x, y, pressed):
        clicked = pressed and not self.was_pressed
        self.was_pressed = pressed
        if not clicked:
            return False
        if self.registration.active:
            self.registration.click(x, y)
            if not self.registration.active:
                self.message = self.registration.message
                self.message_until = time.monotonic() + 5
            return False
        for name, (bx, by, bw, bh) in self.buttons():
            if not (bx <= x < bx + bw and by <= y < by + bh):
                continue
            if name == "EXIT":
                return True
            if name == "VIEW":
                modes = ["FUSION", "VISIBLE", "THERMAL"]
                self.mode = modes[(modes.index(self.mode) + 1) % len(modes)]
            elif name == "ALPHA":
                self.alpha = round((self.alpha + .2) % 1.01, 2)
            elif name == "TEMP":
                self.show_temperatures = not self.show_temperatures
            elif name == "HEAT":
                self.show_heat = not self.show_heat
            elif name == "ALIGN":
                self.calibrating = not self.calibrating
            elif name == "DIST":
                self.alignment.next_distance()
            elif name == "CAL":
                self.calibrating = False
                if self.hot_tracker is not None:
                    self.hot_tracker.clear()
                self.registration.begin()
            elif name == "HOT":
                self.calibrating = False
                self.hot_tracker.toggle()
                self.message = "Tap one numbered hot region" if self.hot_tracker.mode == "PICK" else "Hot tracking off"
                self.message_until = time.monotonic() + 2
            elif name == "SAVE":
                try:
                    self.alignment.save()
                    self.message = "Saved distance profiles and manual scale/shift"
                except Exception as exc:
                    LOG.warning("Save alignment: %s", exc)
                    self.message = "Save failed; see MaixVision console"
                self.message_until = time.monotonic() + 3
            elif name == "FINE":
                self.fine = not self.fine
            else:
                try:
                    self.alignment.adjust(name, self.fine)
                except ValueError as exc:
                    self.message = str(exc)
                    self.message_until = time.monotonic() + 4
            break
        else:
            if (not self.calibrating and self.hot_tracker is not None and
                    self.hot_tracker.select_canvas(x, y, self.alignment)):
                self.message = "Tracking selected hot region"
                self.message_until = time.monotonic() + 2
        return False

    def draw(self, canvas, status):
        if self.hot_tracker is not None and self.hot_tracker.mode != "OFF" and not self.calibrating:
            draw_text_rgb(canvas, self.hot_tracker.status(self.show_temperatures), 8, 105, (255, 155, 75), .48)
        if self.calibrating:
            a = self.alignment
            cv2.drawContours(canvas, a.outlines, -1, (60, 235, 255), 1, cv2.LINE_AA)
            cx, cy = (int(round(v)) for v in a.overlay_centre)
            x, y, w, h, _, _ = a.viewport
            if x <= cx < x + w and y <= cy < y + h:
                cv2.drawMarker(canvas, (cx, cy), (60, 235, 255), cv2.MARKER_CROSS, 17, 1)
            zx, zy, dx, dy = a.tuning
            info = "FOV scale %.2fx / %.2fx | %s | FAR shrink / NEAR enlarge" % (zx, zy, "FINE" if self.fine else "COARSE")
            draw_text_rgb(canvas, info, 8, 105, (60, 235, 255), .43)
        for name, (x, y, w, h) in self.buttons():
            active = ((name == "TEMP" and self.show_temperatures) or
                      (name == "HEAT" and self.show_heat) or
                      (name == "HOT" and self.hot_tracker is not None and self.hot_tracker.mode != "OFF"))
            color = (35, 88, 65) if active else (24, 30, 40)
            cv2.rectangle(canvas, (x, y), (x + w - 2, y + h - 2), color, -1)
            draw_text_rgb(canvas, name, x + 8, y + 22, scale=.48)
        h = canvas.shape[0]
        cv2.rectangle(canvas, (0, h - 28), (canvas.shape[1], h), (20, 24, 30), -1)
        msg = self.message if time.monotonic() < self.message_until else status
        draw_text_rgb(canvas, msg, 8, h - 9, (180, 225, 245), .44)


# ---- hot_tracker ----
"""Thermal-only connected hot regions and one manually selected target.

Candidate coordinates always refer to original, unflipped Thermal160 pixels.
The display uses Alignment.matrix, the same map used by overlay and ROI heat.
"""


def hot_candidates(frame, config):
    if frame is None or not frame["valid_temperature"]:
        return []
    pixels = frame["pixels"]
    if pixels.shape != (THERMAL_H, THERMAL_W):
        return []
    lo, hi = frame["lo"] / 10.0, frame["hi"] / 10.0
    temps = lo + (hi - lo) * np.minimum(pixels.astype(np.float32) / 254.0, 1.0)
    threshold = max(config["hot_min_c"], float(np.median(temps)) + config["hot_delta_c"])
    binary = (temps >= threshold).astype(np.uint8)
    count, labels, stats, centroids = cv2.connectedComponentsWithStats(binary, 8)
    candidates = []
    for label in range(1, count):
        x, y, w, h, area = (int(v) for v in stats[label])
        if area < config["hot_min_area_px"]:
            continue
        values = temps[y:y + h, x:x + w][labels[y:y + h, x:x + w] == label]
        candidates.append({"center": tuple(float(v) for v in centroids[label]),
                           "box": (x, y, w, h), "area": area,
                           "max_c": float(values.max()), "mean_c": float(values.mean()),
                           "label": label})
    candidates.sort(key=lambda item: (-item["max_c"], -item["area"]))
    return candidates[:config["hot_max_candidates"]]


class HotTracker:
    def __init__(self, config):
        self.config = config
        self.mode = "OFF"
        self.candidates = []
        self.selected = None
        self.selected_number = 0
        self.misses = 0
        self.last_seen_at = None
        self.frame = None
        self.thermal_ok = False

    def toggle(self):
        if self.mode == "OFF":
            self.mode = "PICK"
        else:
            self.clear()

    def clear(self):
        self.mode = "OFF"
        self.candidates = []
        self.selected = None
        self.frame = None
        self.last_seen_at = None
        self.misses = 0

    def update(self, frame, now):
        if self.mode == "OFF":
            return
        self.thermal_ok = bool(frame is not None and frame["valid_temperature"] and
                               0 <= now - frame["received_at"] <= self.config["max_thermal_age"])
        if self.thermal_ok and frame is not self.frame:
            self.frame = frame
            self.candidates = hot_candidates(frame, self.config)
            if self.mode == "TRACK":
                self._associate(frame["received_at"])
        elif not self.thermal_ok:
            self.candidates = []
        if (self.mode == "TRACK" and self.last_seen_at is not None and
                now - self.last_seen_at > self.config["hot_track_timeout_s"]):
            self.mode, self.selected = "LOST", None

    def _associate(self, received_at):
        if self.selected is None:
            return
        x, y = self.selected["center"]
        prior_area = self.selected["area"]
        nearest = None
        best = float("inf")
        for item in self.candidates:
            dx, dy = item["center"][0] - x, item["center"][1] - y
            distance = (dx * dx + dy * dy) ** .5
            area_ratio = item["area"] / prior_area
            if distance > self.config["hot_track_gate_px"] or not .25 <= area_ratio <= 4:
                continue
            cost = distance + 2 * abs(np.log(area_ratio))
            if cost < best:
                nearest, best = item, cost
        if nearest is None:
            self.misses += 1
            self.selected = None if self.misses > self.config["hot_track_misses"] else self.selected
            if self.selected is None:
                self.mode = "LOST"
        else:
            self.selected = nearest
            self.misses = 0
            self.last_seen_at = received_at

    def select_canvas(self, x, y, alignment):
        """Pick only inside the calibrated thermal footprint on the visible canvas."""
        if self.mode == "OFF" or not self.thermal_ok or not self.candidates:
            return False
        ix, iy = int(x), int(y)
        if not (0 <= ix < alignment.config["width"] and 0 <= iy < alignment.config["height"]):
            return False
        if not alignment.mask[iy, ix]:
            return False
        try:
            inverse = np.linalg.inv(alignment.matrix)
            point = cv2.perspectiveTransform(np.array([[[x, y]]], np.float64), inverse).reshape(2)
        except (ValueError, np.linalg.LinAlgError, cv2.error):
            return False
        px, py = point
        if not (0 <= px < THERMAL_W and 0 <= py < THERMAL_H):
            return False
        nearest, best = None, float("inf")
        for item in self.candidates:
            cx, cy = item["center"]
            distance = ((cx - px) ** 2 + (cy - py) ** 2) ** .5
            bx, by, bw, bh = item["box"]
            inside = bx - 2 <= px < bx + bw + 2 and by - 2 <= py < by + bh + 2
            if (inside or distance <= max(6, .6 * max(bw, bh))) and distance < best:
                nearest, best = item, distance
        if nearest is None:
            return False
        self.selected = nearest
        self.selected_number += 1
        self.mode, self.misses = "TRACK", 0
        self.last_seen_at = self.frame["received_at"]
        return True

    def status(self, show_temperature=True):
        if self.mode == "OFF":
            return ""
        if not self.thermal_ok:
            return "HOT WAIT THERMAL"
        if self.mode == "PICK":
            return "HOT PICK %d" % len(self.candidates)
        if self.mode == "LOST":
            return "HOT LOST - tap another"
        if self.misses:
            return "HOT HOLD %d/%d" % (self.misses, self.config["hot_track_misses"])
        if show_temperature:
            return "HOT #%d max~%.1fC" % (self.selected_number, self.selected["max_c"])
        return "HOT #%d" % self.selected_number

    def draw(self, canvas, alignment, thermal_visible, show_temperature=True):
        if not thermal_visible or not self.thermal_ok or self.mode == "OFF":
            return
        for index, item in enumerate(self.candidates, 1):
            point = cv2.perspectiveTransform(
                np.array([[[item["center"][0], item["center"][1]]]], np.float64),
                alignment.matrix).reshape(2)
            x, y = (int(round(v)) for v in point)
            if not (0 <= x < canvas.shape[1] and 64 <= y < canvas.shape[0] - 28 and
                    alignment.mask[y, x]):
                continue
            is_selected = self.mode == "TRACK" and self.misses == 0 and item is self.selected
            color = (255, 80, 40) if is_selected else (255, 210, 70)
            cv2.drawMarker(canvas, (x, y), color, cv2.MARKER_CROSS, 17 if is_selected else 10, 2)
            label = "%d %.1fC" % (index, item["max_c"]) if show_temperature else str(index)
            draw_text_rgb(canvas, label, x + 7, y - 6, color, .42)
            if is_selected:
                bx, by, bw, bh = item["box"]
                corners = np.array([[[bx, by]], [[bx + bw, by]],
                                    [[bx + bw, by + bh]], [[bx, by + bh]]], np.float64)
                quad = cv2.perspectiveTransform(corners, alignment.matrix).reshape(-1, 2)
                cv2.polylines(canvas, [np.rint(quad).astype(np.int32)], True, color, 2, cv2.LINE_AA)


# ---- rtsp_jpeg ----
"""Small RTSP/1.0 server: baseline RTP/JPEG over TCP (RFC 2326 + RFC 2435).

No camera binding: only receives the application's fully composed RGB images.
One pending image per encoder/client bounds latency and memory for slow clients.
"""
import re
import secrets
import socket
from urllib.parse import urlsplit


def parse_jpeg(jpeg):
    if jpeg[:2] != b"\xff\xd8" or jpeg[-2:] != b"\xff\xd9":
        raise ValueError("JPEG SOI/EOI missing")
    pos, tables, info = 2, {}, None
    while pos + 4 <= len(jpeg):
        if jpeg[pos] != 255:
            raise ValueError("Invalid JPEG marker")
        while jpeg[pos] == 255:
            pos += 1
        marker = jpeg[pos]
        size = int.from_bytes(jpeg[pos + 1:pos + 3], "big")
        if size < 2 or pos + 1 + size > len(jpeg):
            raise ValueError("Truncated JPEG segment")
        data = jpeg[pos + 3:pos + 1 + size]
        pos += 1 + size
        if marker == 0xDB:
            off = 0
            while off < len(data):
                table = data[off]
                if table >> 4 != 0 or off + 65 > len(data):
                    raise ValueError("Only 8-bit JPEG quantization supported")
                tables[table & 15] = data[off + 1:off + 65]
                off += 65
        elif marker == 0xC0:
            if len(data) != 15 or data[0] != 8 or data[5] != 3:
                raise ValueError("Expected 3-component baseline JPEG")
            height, width = struct.unpack_from(">HH", data, 1)
            sampling = data[7]
            if (sampling not in (0x21, 0x22) or data[10] != 0x11 or data[13] != 0x11 or
                    data[8] != 0 or data[11] != 1 or data[14] != 1):
                raise ValueError("RTP/JPEG requires YUV 4:2:2 or 4:2:0 with Q tables 0/1")
            if width % 8 or height % 8 or not 8 <= width <= 2040 or not 8 <= height <= 2040:
                raise ValueError("Stream dimensions must be multiples of 8 and <=2040")
            info = {"width": width, "height": height, "type": 1 if sampling == 0x22 else 0}
        elif marker in (0xC1, 0xC2, 0xDD):
            raise ValueError("Progressive/extended/restart JPEG is unsupported")
        elif marker == 0xDA:
            if info is None or 0 not in tables or 1 not in tables:
                raise ValueError("Missing JPEG frame header or quantization tables")
            if len(data) != 10 or data[0] != 3 or data[2] != 0 or data[4] != 0x11 or data[6] != 0x11:
                raise ValueError("Expected standard interleaved JPEG scan")
            info["tables"] = tables[0] + tables[1]
            info["scan"] = jpeg[pos:-2]
            if not info["scan"] or len(info["scan"]) >= 1 << 24:
                raise ValueError("Invalid JPEG scan length")
            return info
    raise ValueError("No JPEG scan")


def jpeg_rtp_packets(frame, timestamp, sequence, ssrc, mtu=1400):
    offset = 0
    scan = frame["scan"]
    while offset < len(scan):
        quant = struct.pack(">BBH", 0, 0, len(frame["tables"])) + frame["tables"] if offset == 0 else b""
        count = min(mtu - 20 - len(quant), len(scan) - offset)
        if count <= 0:
            raise ValueError("RTP MTU too small")
        last = offset + count == len(scan)
        rtp = struct.pack(">BBHII", 0x80, 26 | (0x80 if last else 0), sequence & 65535, timestamp & 0xffffffff, ssrc)
        header = b"\0" + offset.to_bytes(3, "big") + bytes((frame["type"], 255, frame["width"] // 8, frame["height"] // 8))
        yield rtp + header + quant + scan[offset:offset + count]
        offset += count
        sequence += 1


def rtcp_report(ssrc, timestamp, packet_count, byte_count):
    ntp = time.time() + 2208988800
    seconds = int(ntp)
    report = struct.pack(">BBHIIIIII", 0x80, 200, 6, ssrc, seconds,
                         int((ntp - seconds) * (1 << 32)), timestamp,
                         packet_count & 0xffffffff, byte_count & 0xffffffff)
    cname = b"maixcam2-fusion"
    chunk = struct.pack(">I", ssrc) + bytes((1, len(cname))) + cname + b"\0"
    chunk += b"\0" * (-len(chunk) % 4)
    return report + struct.pack(">BBH", 0x81, 202, len(chunk) // 4) + chunk


class RtspClient:
    def __init__(self, server, conn, address):
        self.server, self.conn, self.address = server, conn, address
        conn.settimeout(1.0)
        conn.setsockopt(socket.IPPROTO_TCP, socket.TCP_NODELAY, 1)
        self.alive = threading.Event()
        self.alive.set()
        self.playing = threading.Event()
        self.write_lock = threading.Lock()
        self.condition = threading.Condition()
        self.pending = None
        self.channel, self.rtcp_channel = 0, 1
        self.session = secrets.token_hex(8)
        self.setup_done = False
        self.sequence, self.ssrc = secrets.randbits(16), secrets.randbits(32)
        self.packet_count = self.byte_count = 0
        self.last_rtcp = 0.0
        self.reader = threading.Thread(target=self._serve, name="rtsp-control", daemon=True)
        self.writer = threading.Thread(target=self._write_loop, name="rtsp-video", daemon=True)

    def start(self):
        self.writer.start()
        self.reader.start()

    def publish(self, frame, timestamp):
        if self.playing.is_set():
            with self.condition:
                self.pending = frame, timestamp
                self.condition.notify()

    def _response(self, cseq, code=200, reason="OK", headers=None, body=b""):
        h = {"CSeq": cseq, "Server": "MaixFusion-RTSP", "Content-Length": str(len(body))}
        if headers:
            h.update(headers)
        message = "RTSP/1.0 %d %s\r\n" % (code, reason)
        message += "".join("%s: %s\r\n" % (k, v) for k, v in h.items()) + "\r\n"
        with self.write_lock:
            self.conn.sendall(message.encode("ascii") + body)

    def _request(self, request):
        lines = request.decode("latin1").split("\r\n")
        method, url, version = lines[0].split(" ", 2)
        headers = {}
        for line in lines[1:]:
            if ":" in line:
                key, value = line.split(":", 1)
                headers[key.lower()] = value.strip()
        cseq = headers.get("cseq", "0")
        path = urlsplit(url).path.rstrip("/")
        if method != "OPTIONS" and path not in ("/live", "/live/trackID=0"):
            self._response(cseq, 404, "Not Found")
            return
        if method == "OPTIONS":
            self._response(cseq, headers={"Public": "OPTIONS, DESCRIBE, SETUP, PLAY, PAUSE, GET_PARAMETER, TEARDOWN"})
        elif method == "DESCRIBE":
            base = url.rstrip("/") + "/"
            sdp = ("v=0\r\no=- 1 1 IN IP4 0.0.0.0\r\ns=MaixCAM2 Thermal YOLO Fusion\r\n"
                   "c=IN IP4 0.0.0.0\r\nt=0 0\r\na=control:*\r\n"
                   "m=video 0 RTP/AVP 26\r\na=rtpmap:26 JPEG/90000\r\n"
                   "a=framerate:%d\r\na=control:trackID=0\r\n" % self.server.fps).encode("ascii")
            self._response(cseq, headers={"Content-Type": "application/sdp", "Content-Base": base}, body=sdp)
        elif method == "SETUP":
            transport = headers.get("transport", "")
            match = re.search(r"interleaved=(\d+)-(\d+)", transport, re.I)
            if "RTP/AVP/TCP" not in transport.upper() or not match:
                self._response(cseq, 461, "Unsupported Transport")
                return
            channels = tuple(map(int, match.groups()))
            if channels[0] == channels[1] or not all(0 <= ch <= 255 for ch in channels):
                self._response(cseq, 461, "Unsupported Transport")
                return
            self.channel, self.rtcp_channel = channels
            self.setup_done = True
            self._response(cseq, headers={"Session": self.session,
                "Transport": "RTP/AVP/TCP;unicast;interleaved=%d-%d;ssrc=%08X" % (*channels, self.ssrc)})
        elif method in ("PLAY", "PAUSE", "TEARDOWN", "GET_PARAMETER"):
            session = headers.get("session", "").split(";")[0]
            if not self.setup_done or session != self.session:
                self._response(cseq, 454, "Session Not Found")
                return
            if method in ("PAUSE", "TEARDOWN"):
                self.playing.clear()
            self._response(cseq, headers={"Session": self.session})
            if method == "PLAY":
                self.playing.set()
            elif method == "TEARDOWN":
                self.close()
        else:
            self._response(cseq, 405, "Method Not Allowed")

    def _serve(self):
        buffer = bytearray()
        last_request = time.monotonic()
        try:
            while self.alive.is_set():
                try:
                    data = self.conn.recv(8192)
                except socket.timeout:
                    if not self.setup_done and time.monotonic() - last_request > 15:
                        break
                    continue
                if not data:
                    break
                buffer.extend(data)
                if len(buffer) > 65536:
                    raise ValueError("RTSP request too large")
                while buffer:
                    # Ignore incoming RTP/RTCP interleaved packets from the client.
                    if buffer[0] == 36:
                        if len(buffer) < 4:
                            break
                        end = 4 + int.from_bytes(buffer[2:4], "big")
                        if len(buffer) < end:
                            break
                        del buffer[:end]
                        continue
                    idx = buffer.find(b"\r\n\r\n")
                    if idx < 0:
                        break
                    head = bytes(buffer[:idx + 4])
                    match = re.search(rb"(?im)^Content-Length:\s*(\d+)", head)
                    content_len = int(match.group(1)) if match else 0
                    if content_len > 8192:
                        raise ValueError("RTSP body too large")
                    end = idx + 4 + content_len
                    if len(buffer) < end:
                        break
                    del buffer[:end]
                    last_request = time.monotonic()
                    self._request(head)
        except (OSError, ValueError) as exc:
            LOG.debug("RTSP control ended: %s", exc)
        finally:
            self.close()
            self.server.remove(self)

    def _write_loop(self):
        try:
            while self.alive.is_set():
                with self.condition:
                    if self.pending is None:
                        self.condition.wait(timeout=.5)
                    pending, self.pending = self.pending, None
                if pending is None or not self.playing.is_set():
                    continue
                frame, timestamp = pending
                with self.write_lock:
                    for packet in jpeg_rtp_packets(frame, timestamp, self.sequence, self.ssrc):
                        self.conn.sendall(struct.pack(">BBH", 36, self.channel, len(packet)) + packet)
                        self.sequence = (self.sequence + 1) & 65535
                        self.packet_count += 1
                        self.byte_count += len(packet) - 12
                    if time.monotonic() - self.last_rtcp > 3:
                        report = rtcp_report(self.ssrc, timestamp, self.packet_count, self.byte_count)
                        self.conn.sendall(struct.pack(">BBH", 36, self.rtcp_channel, len(report)) + report)
                        self.last_rtcp = time.monotonic()
        except OSError as exc:
            LOG.debug("RTSP slow/disconnected client: %s", exc)
            self.close()

    def close(self):
        self.alive.clear()
        self.playing.clear()
        with self.condition:
            self.condition.notify_all()
        try:
            self.conn.shutdown(socket.SHUT_RDWR)
        except OSError:
            pass
        self.conn.close()


class JpegRtspServer:
    def __init__(self, host="0.0.0.0", port=8554, fps=8, quality=70, max_clients=2):
        self.host, self.port, self.fps, self.quality = host, port, fps, quality
        self.max_clients = max_clients
        self.clients, self.clients_lock = [], threading.Lock()
        self.stop_event = threading.Event()
        self.condition = threading.Condition()
        self.pending = None
        self.last_submit = 0.0
        self.error = ""
        self.encoded = 0
        self.listener = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        try:
            self.listener.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            self.listener.bind((host, port))
            self.port = self.listener.getsockname()[1]
            self.listener.listen(max_clients)
            self.listener.settimeout(.5)
        except Exception:
            self.listener.close()
            raise
        self.accept_thread = threading.Thread(target=self._accept, name="rtsp-accept", daemon=True)
        self.encode_thread = threading.Thread(target=self._encode, name="rtsp-jpeg", daemon=True)
        self.accept_thread.start()
        self.encode_thread.start()

    def client_count(self):
        with self.clients_lock:
            return sum(c.playing.is_set() and c.alive.is_set() for c in self.clients)

    def remove(self, client):
        with self.clients_lock:
            if client in self.clients:
                self.clients.remove(client)

    def _accept(self):
        while not self.stop_event.is_set():
            try:
                conn, address = self.listener.accept()
            except socket.timeout:
                continue
            except OSError:
                break
            with self.clients_lock:
                if len(self.clients) >= self.max_clients:
                    conn.close()
                    continue
                client = RtspClient(self, conn, address)
                self.clients.append(client)
            client.start()

    def submit(self, rgb, now=None):
        now = time.monotonic() if now is None else now
        if now - self.last_submit < 1.0 / self.fps or not self.client_count():
            return
        self.last_submit = now
        with self.condition:
            self.pending = rgb.copy(), int(now * 90000) & 0xffffffff
            self.condition.notify()

    def _encode(self):
        while not self.stop_event.is_set():
            with self.condition:
                if self.pending is None:
                    self.condition.wait(timeout=.5)
                pending, self.pending = self.pending, None
            if pending is None:
                continue
            try:
                rgb, timestamp = pending
                bgr = cv2.cvtColor(rgb, cv2.COLOR_RGB2BGR)
                ok, jpeg = cv2.imencode(".jpg", bgr, [cv2.IMWRITE_JPEG_QUALITY, self.quality,
                    cv2.IMWRITE_JPEG_PROGRESSIVE, 0, cv2.IMWRITE_JPEG_OPTIMIZE, 0,
                    cv2.IMWRITE_JPEG_RST_INTERVAL, 0])
                if not ok:
                    raise RuntimeError("OpenCV JPEG encoding failed")
                frame = parse_jpeg(jpeg.tobytes())
                with self.clients_lock:
                    clients = list(self.clients)
                for client in clients:
                    client.publish(frame, timestamp)
                self.encoded += 1
                self.error = ""
            except Exception as exc:
                if not self.error:
                    LOG.exception("RTSP encoding failed")
                self.error = str(exc)

    def close(self):
        self.stop_event.set()
        with self.condition:
            self.condition.notify_all()
        self.listener.close()
        with self.clients_lock:
            clients = list(self.clients)
        for client in clients:
            client.close()
        for thread in (self.accept_thread, self.encode_thread):
            thread.join(timeout=2.0)
        for client in clients:
            client.reader.join(timeout=1.5)
            client.writer.join(timeout=1.5)


# ---- pipeline ----
"""YOLO process isolation: bounded latest-frame mailbox, private socket IPC.

Avoid relying on native inference to release the Python GIL. No network port,
pickle deserialization, input FIFO, or shared camera/model object between processes.
"""
import subprocess
import sys


def ipc_send(sock, header, payload=b""):
    header = dict(header, payload_bytes=len(payload))
    encoded = json.dumps(header).encode("utf-8")
    if len(encoded) > 65536 or len(payload) > 32 * 1024 * 1024:
        raise ValueError("IPC message exceeds bound")
    sock.sendall(struct.pack(">I", len(encoded)) + encoded)
    if payload:
        sock.sendall(payload)


def ipc_exact(sock, length):
    data = bytearray()
    while len(data) < length:
        chunk = sock.recv(min(length - len(data), 1024 * 1024))
        if not chunk:
            raise EOFError("YOLO worker connection closed")
        data.extend(chunk)
    return bytes(data)


def ipc_receive(sock):
    length = struct.unpack(">I", ipc_exact(sock, 4))[0]
    if not 1 <= length <= 65536:
        raise ValueError("Invalid IPC header size")
    header = json.loads(ipc_exact(sock, length))
    size = header.get("payload_bytes", 0)
    if not isinstance(size, int) or not 0 <= size <= 32 * 1024 * 1024:
        raise ValueError("Invalid IPC payload size")
    return header, ipc_exact(sock, size)


def run_yolo_worker(fd, model_path, kind):
    """Only this process initializes/uses the NPU model. RGB capture stays in parent."""
    channel = socket.socket(fileno=fd)
    detector = None
    try:
        from maix import image, nn
        detector = getattr(nn, kind)(model=model_path, dual_buff=False)
        width, height = detector.input_width(), detector.input_height()
        ipc_send(channel, {"event": "ready", "width": width, "height": height})
        while True:
            header, data = ipc_receive(channel)
            if header.get("event") == "stop":
                break
            if header.get("event") != "frame" or len(data) != width * height * 3:
                raise ValueError("Invalid inference frame")
            rgb = np.frombuffer(data, np.uint8).reshape(height, width, 3)
            img = image.cv2image(rgb, bgr=False, copy=True)
            if img.format() != detector.input_format():
                img = img.to_format(detector.input_format())
            started = time.monotonic()
            objects = detector.detect(img, conf_th=header["confidence"], iou_th=header["iou"])
            detections = []
            for obj in sorted(objects, key=lambda item: item.score, reverse=True)[:header["max_objects"]]:
                label = str(detector.labels[obj.class_id]).encode("ascii", "replace").decode("ascii")[:24]
                detections.append({"box": [obj.x, obj.y, obj.w, obj.h], "score": float(obj.score),
                                   "label": label, "captured_at": header["captured_at"]})
            ipc_send(channel, {"event": "result", "captured_at": header["captured_at"],
                               "inference_ms": (time.monotonic() - started) * 1000,
                               "detections": detections})
    except EOFError:
        pass
    except Exception as exc:
        try:
            ipc_send(channel, {"event": "error", "error": str(exc)})
        except OSError:
            pass
        raise
    finally:
        detector = None
        channel.close()


class InlineDetector:
    """One Maix hardware process; scheduled inference still blocks the calling loop."""
    def __init__(self, config, model, image_module):
        self.config, self.model, self.image = config, model, image_module
        self.enabled, self.latest, self.error = True, None, ""
        self.completed = self.replaced = 0
        self.last_started = None

    @classmethod
    def launch(cls, config, model_path, kind):
        from maix import image, nn
        model = getattr(nn, kind)(model=model_path, dual_buff=False)
        return cls(config, model, image), (model.input_width(), model.input_height())

    def set_enabled(self, enabled):
        if self.enabled != enabled:
            self.enabled = enabled
            self.latest = None
            self.last_started = None

    def submit(self, rgb, captured_at):
        if not self.enabled or self.error:
            return
        now = time.monotonic()
        cap = self.config["inference_fps"]
        if cap and self.last_started is not None and now - self.last_started < 1 / cap:
            return
        self.last_started = now
        try:
            img = self.image.cv2image(rgb, bgr=False, copy=True)
            if img.format() != self.model.input_format():
                img = img.to_format(self.model.input_format())
            started = time.monotonic()
            objects = self.model.detect(img, conf_th=self.config["confidence"], iou_th=self.config["iou"])
            detections = []
            for obj in sorted(objects, key=lambda item: item.score, reverse=True)[:self.config["max_objects"]]:
                label = str(self.model.labels[obj.class_id]).encode("ascii", "replace").decode("ascii")[:24]
                detections.append({"box": [obj.x, obj.y, obj.w, obj.h], "score": float(obj.score),
                                   "label": label, "captured_at": captured_at})
            self.latest = {"captured_at": captured_at, "detections": detections,
                           "inference_ms": (time.monotonic() - started) * 1000}
            self.completed += 1
        except Exception as exc:
            self.error, self.latest = str(exc), None
            LOG.exception("Inline YOLO failed; RGB/thermal preview continues")

    def snapshot(self, now):
        result = self.latest
        stats = {"completed": self.completed, "replaced": 0, "error": self.error,
                 "age": None, "inference_ms": None}
        if result is None or not self.enabled or self.error:
            return [], stats
        age = now - result["captured_at"]
        stats.update(age=age, inference_ms=result["inference_ms"])
        return (result["detections"] if 0 <= age <= self.config["max_detection_age"] else []), stats

    def close(self):
        self.enabled, self.latest, self.model = False, None, None


class AsyncDetector:
    def __init__(self, config, channel, process=None):
        self.config, self.channel, self.process = config, channel, process
        self.condition = threading.Condition()
        self.stopped = False
        self.pending = None
        self.generation = 0
        self.enabled = True
        self.latest = None
        self.completed = self.replaced = 0
        self.error = ""
        self.thread = threading.Thread(target=self._work, name="yolo-ipc", daemon=True)
        self.thread.start()

    @classmethod
    def launch(cls, config, entry_path, model_path, kind):
        if os.name != "posix":
            raise RuntimeError("NPU process mode runs on the Linux board")
        parent, child = socket.socketpair()
        process = None
        try:
            # pass_fds creates a private inherited channel, not an exposed server.
            process = subprocess.Popen([sys.executable, "-u", entry_path, "--yolo-worker",
                str(child.fileno()), model_path, kind], pass_fds=(child.fileno(),), close_fds=True)
            child.close()
            parent.settimeout(120)
            ready, _ = ipc_receive(parent)
            if ready.get("event") != "ready":
                raise RuntimeError("YOLO startup failed: " + str(ready))
            width, height = int(ready["width"]), int(ready["height"])
            if not 1 <= width <= 4096 or not 1 <= height <= 4096 or width * height * 3 > 32 * 1024 * 1024:
                raise ValueError("Invalid model input size")
            parent.settimeout(30)
            return cls(config, parent, process), (width, height)
        except Exception:
            child.close()
            parent.close()
            if process is not None:
                process.terminate()
                try:
                    process.wait(timeout=3)
                except subprocess.TimeoutExpired:
                    process.kill()
                    process.wait(timeout=3)
            raise

    def submit(self, rgb, captured_at):
        # Ownership: producer must not modify this new RGB array after submission.
        with self.condition:
            if self.stopped or not self.enabled or self.error:
                return
            if self.pending is not None:
                self.replaced += 1
            self.pending = (rgb, captured_at, self.generation)
            self.condition.notify()

    def set_enabled(self, enabled):
        with self.condition:
            if self.enabled != enabled:
                self.enabled = enabled
                self.generation += 1
                self.latest = self.pending = None

    def snapshot(self, now):
        with self.condition:
            result = self.latest
            stats = {"completed": self.completed, "replaced": self.replaced, "error": self.error,
                     "age": None, "inference_ms": None}
            if result is None or not self.enabled or self.error:
                return [], stats
            age = now - result["captured_at"]
            stats.update(age=age, inference_ms=result["inference_ms"])
            if age < 0 or age > self.config["max_detection_age"]:
                return [], stats
            return result["detections"], stats

    def _work(self):
        last_started = 0.
        try:
            while True:
                with self.condition:
                    while self.pending is None and not self.stopped:
                        self.condition.wait(timeout=.5)
                    if self.stopped:
                        break
                    cap = self.config["inference_fps"]
                    delay = max(0, 1 / cap - (time.monotonic() - last_started)) if cap else 0
                    if delay:
                        self.condition.wait(timeout=delay)
                        continue
                    rgb, captured_at, generation = self.pending
                    self.pending = None
                last_started = time.monotonic()
                ipc_send(self.channel, {"event": "frame", "captured_at": captured_at,
                    "confidence": self.config["confidence"], "iou": self.config["iou"],
                    "max_objects": self.config["max_objects"]}, np.ascontiguousarray(rgb).tobytes())
                # Drop our image reference while waiting; only the single pending frame is retained.
                del rgb
                result, _ = ipc_receive(self.channel)
                if result.get("event") != "result":
                    raise RuntimeError("YOLO worker failed: " + str(result))
                if result.get("captured_at") != captured_at:
                    raise ValueError("Inference response timestamp does not match its input")
                with self.condition:
                    self.completed += 1
                    if self.enabled and generation == self.generation:
                        self.latest = result
        except Exception as exc:
            with self.condition:
                if not self.stopped:
                    self.error = str(exc)
                    self.latest = self.pending = None
                    LOG.exception("YOLO process unavailable; RGB/thermal preview continues")

    def close(self):
        with self.condition:
            self.stopped = True
            self.pending = self.latest = None
            self.condition.notify_all()
        try:
            self.channel.shutdown(socket.SHUT_RDWR)
        except OSError:
            pass
        self.channel.close()
        self.thread.join(timeout=2)
        if self.process is not None:
            try:
                self.process.wait(timeout=2)
            except subprocess.TimeoutExpired:
                self.process.terminate()
                try:
                    self.process.wait(timeout=2)
                except subprocess.TimeoutExpired:
                    self.process.kill()
                    self.process.wait(timeout=2)


class RateMeter:
    """Recent count deltas, not model latency or a lifetime-average FPS."""
    def __init__(self):
        self.at, self.count = time.monotonic(), 0
        self.fps = 0.

    def update(self, count, now):
        if now - self.at >= 1:
            self.fps = max(0, count - self.count) / (now - self.at)
            self.at, self.count = now, count
        return self.fps


# ---- runtime ----
"""Hardware entry point and an explicitly synthetic PC demo for streaming tests."""
import sys


def camera_image_to_rgb(frame, image_module):
    """Return an owned RGB array; image2cv cannot ensure BGR with copy=False."""
    if frame.format() != image_module.Format.FMT_RGB888:
        frame = frame.to_format(image_module.Format.FMT_RGB888)
    return image_module.image2cv(frame, ensure_bgr=False, copy=True)


class BoardTrace:
    """Native faulthandler timer can report Python stacks even during a held GIL."""
    def __init__(self, enabled):
        self.enabled = enabled
        self.handler = None
        if enabled:
            try:
                import faulthandler
                faulthandler.dump_traceback_later(15, repeat=True)
                self.handler = faulthandler
            except (RuntimeError, OSError, ValueError) as exc:
                LOG.warning("Stack watchdog unavailable: %s", exc)

    def step(self, label, attempt=0):
        if self.enabled and attempt < 3:
            LOG.info("STEP %s [attempt %d]", label, attempt + 1)

    def progress(self):
        if self.handler:
            self.handler.cancel_dump_traceback_later()
            self.handler.dump_traceback_later(15, repeat=True)

    def close(self):
        if self.handler:
            self.handler.cancel_dump_traceback_later()


def validate_config(config):
    for key in ("width", "height"):
        value = config[key]
        if not isinstance(value, int) or value % 8 or not 160 <= value <= 2040:
            raise ValueError(key + " must be a multiple of 8 in [160,2040]")
    if not 0 < config["stream_fps"] <= 60 or not 1 <= config["jpeg_quality"] <= 95:
        raise ValueError("Invalid stream_fps/jpeg_quality")
    if not 0 <= config["alpha"] <= 1 or config["loop_fps"] < 0:
        raise ValueError("Invalid alpha/loop_fps")
    if config["camera_fps"] <= 0 or config["inference_fps"] < 0:
        raise ValueError("Invalid camera/inference FPS")
    if config["max_detection_age"] <= 0 or config["max_detection_thermal_delta"] <= 0:
        raise ValueError("Invalid detection time limits")
    if config["max_thermal_age"] <= 0 or config["max_pair_delta"] <= 0:
        raise ValueError("Thermal time limits must be positive")
    if config["detector_mode"] not in ("inline", "process"):
        raise ValueError("detector_mode must be inline or process")
    if not 1 <= config["camera_read_timeout_ms"] <= 1000 or config["camera_stall_seconds"] <= 0:
        raise ValueError("Invalid camera timeout")
    if (not -100 <= config["hot_min_c"] <= 320 or config["hot_delta_c"] <= 0 or
            not 1 <= config["hot_min_area_px"] <= PIXELS or
            not 1 <= config["hot_max_candidates"] <= 100 or
            config["hot_track_gate_px"] <= 0 or
            not 0 <= config["hot_track_misses"] <= 20 or
            config["hot_track_timeout_s"] <= 0):
        raise ValueError("Invalid hot-region tracking configuration")


def select_model(config):
    if config["model_path"]:
        candidates = [(config["model_path"], config["model_type"])]
    else:
        candidates = [("/root/models/yolo11n.mud", "YOLO11"),
                      ("/root/models/yolo11s.mud", "YOLO11"),
                      ("/root/models/yolov8n.mud", "YOLOv8")]
    for path, model_type in candidates:
        if os.path.isfile(path):
            return path, model_type
    raise FileNotFoundError(
        "No supported MaixCAM2 YOLO model found. Upload its .mud AND referenced .axmodel files "
        "to /root/models, then set CONFIG['model_path'] and CONFIG['model_type']. Tried: "
        + ", ".join(path for path, _ in candidates))


def touch_to_canvas(x, y, disp_w, disp_h, width, height):
    scale = min(disp_w / width, disp_h / height)
    ox, oy = (disp_w - width * scale) / 2, (disp_h - height * scale) / 2
    return (x - ox) / scale, (y - oy) / scale


def rtsp_addresses(port):
    addresses = set()
    try:
        for item in socket.getaddrinfo(socket.gethostname(), None, socket.AF_INET):
            ip = item[4][0]
            if not ip.startswith("127."):
                addresses.add(ip)
    except OSError:
        pass
    # Local read-only enumeration also covers USB gadget interfaces.
    try:
        import subprocess
        info = subprocess.check_output(["ip", "-j", "-4", "addr"], timeout=2)
        for iface in json.loads(info):
            for address in iface.get("addr_info", []):
                ip = address.get("local", "")
                if ip and not ip.startswith("127."):
                    addresses.add(ip)
    except Exception:
        pass
    return ["rtsp://%s:%d/live" % (ip, port) for ip in sorted(addresses)] or ["rtsp://<DEVICE_IP>:%d/live" % port]


def run_board():
    from maix import app, camera, display, image, touchscreen
    from maix import sys as maix_sys
    import maix

    logging.basicConfig(level=logging.INFO, format="%(asctime)s %(levelname)s %(message)s")
    c = dict(CONFIG)
    validate_config(c)
    if maix_sys.device_name() != "MaixCAM2":
        raise RuntimeError("This app targets MaixCAM2 + Thermal160 UART telemetry30")
    LOG.info("MaixPy %s, Python %s", getattr(maix, "__version__", "unknown"), sys.version.split()[0])
    LOG.info("RTSP/JPEG output contains the composed thermal + YOLO image; use TCP transport")
    cam = disp = thermal = stream = detector = None
    trace = BoardTrace(c["diagnostic_trace"])
    try:
        trace.step("display.init")
        disp = display.Display()
        path, kind = select_model(c)
        if kind not in ("YOLO11", "YOLOv8", "YOLOv5"):
            raise ValueError("model_type must be YOLO11, YOLOv8 or YOLOv5")
        LOG.info("Loading %s: %s; detector_mode=%s", kind, path, c["detector_mode"])
        trace.step("detector.init")
        if c["detector_mode"] == "process":
            LOG.warning("Experimental cross-process Maix hardware mode; not validated on this board")
            detector, (iw, ih) = AsyncDetector.launch(c, os.path.abspath(__file__), path, kind)
        else:
            detector, (iw, ih) = InlineDetector.launch(c, path, kind)
        trace.step("camera.init")
        cam = camera.Camera(iw, ih, image.Format.FMT_RGB888, fps=c["camera_fps"])
        LOG.info("Requested RGB %dfps; composition cap=%s; independent thermal UART", c["camera_fps"], c["loop_fps"] or "none")
        try:
            ts = touchscreen.TouchScreen()
        except Exception as exc:
            LOG.warning("Touch unavailable; use MaixVision Stop / USER key: %s", exc)
            ts = None
        # Both single-file and project execution work; no imported sibling modules.
        app_dir = os.path.dirname(os.path.abspath(__file__)) if "__file__" in globals() else os.getcwd()
        alignment = Alignment(c, (iw, ih), c.get("alignment_path") or os.path.join(app_dir, "alignment.json"))
        hot_tracker = HotTracker(c)
        ui = TouchUI(alignment, hot_tracker)
        if c["rtsp_enabled"]:
            stream = JpegRtspServer(c["rtsp_host"], c["rtsp_port"], c["stream_fps"], c["jpeg_quality"], c["max_clients"])
            for address in rtsp_addresses(stream.port):
                LOG.info("PLAY: %s", address)
                LOG.info('ffplay -rtsp_transport tcp -i "%s"', address)
        thermal = ThermalReader(c)
        thermal.start()
        last_stats = time.monotonic()
        frames = 0
        attempts = 0
        last_camera_frame = time.monotonic()
        last_camera_warning = last_camera_frame
        visual_rate, thermal_rate, ai_rate, stream_rate = RateMeter(), RateMeter(), RateMeter(), RateMeter()
        while not app.need_exit():
            started = time.monotonic()
            trace.step("touch.read", attempts)
            if ts is not None:
                # Latest accepted thermal frame is used for touch picking; its age is checked.
                pick_frame, _, _ = thermal.snapshot()
                hot_tracker.update(pick_frame, started)
                tx, ty, pressed = ts.read()
                tx, ty = touch_to_canvas(tx, ty, disp.width(), disp.height(), c["width"], c["height"])
                if ui.touch(tx, ty, pressed):
                    app.set_exit_flag(True)
                    break
            trace.step("camera.read", attempts)
            camera_img = cam.read(block=True, block_ms=c["camera_read_timeout_ms"])
            visible_at = time.monotonic()
            attempts += 1
            if camera_img is None:
                if visible_at - last_camera_frame >= c["camera_stall_seconds"]:
                    raise RuntimeError("Camera produced no frames for %.1fs; check sensor/FPS mode and restart the board" % (visible_at - last_camera_frame))
                if visible_at - last_camera_warning >= 2:
                    LOG.warning("CAMERA WAIT: no frame for %.1fs", visible_at - last_camera_frame)
                    last_camera_warning = visible_at
                time.sleep(.005)
                continue
            if frames == 0:
                LOG.info("Camera frame format %s; preserving RGB channel order", camera_img.format())
            last_camera_frame = visible_at
            trace.step("image.to_rgb", attempts - 1)
            thermal_frame, reader_status, thermal_count = thermal.snapshot()
            hot_tracker.update(thermal_frame, visible_at)
            rgb = camera_image_to_rgb(camera_img, image)
            # rgb owns its pixels; release the camera view before acquiring another frame.
            del camera_img
            trace.step("detector.submit", attempts - 1)
            detector.set_enabled(not ui.registration.active)
            detector.submit(rgb, visible_at)
            now = time.monotonic()
            detections, ai_stats = detector.snapshot(now)
            trace.step("compose", attempts - 1)
            ui.registration.observe(rgb, thermal_frame, visible_at, now)
            canvas, _, thermal_status = compose(rgb, detections, thermal_frame, alignment, now,
                                                visible_at, ui.mode, ui.alpha,
                                                ui.show_temperatures, ui.show_heat)
            _, thermal_visible, _ = thermal_state(thermal_frame, visible_at, now, c)
            hot_tracker.draw(canvas, alignment, thermal_visible, ui.show_temperatures)
            if stream is None:
                stream_status = "RTSP OFF"
            elif stream.error:
                stream_status = "RTSP ENCODE ERROR (console)"
            else:
                stream_status = "RTSP:%d clients:%d" % (stream.port, stream.client_count())
            status = "V%.1f T%.1f AI%.1f NET%.1f | %s" % (visual_rate.fps, thermal_rate.fps, ai_rate.fps, stream_rate.fps, stream_status)
            if ai_stats["error"]:
                status = "YOLO ERROR (console) | " + status
            elif ai_stats["age"] is not None:
                status += " | AI age %.0fms" % (ai_stats["age"] * 1000)
            if hot_tracker.mode != "OFF":
                status += " | " + hot_tracker.status(ui.show_temperatures)
            ui.draw(canvas, status)
            if ui.registration.active:
                canvas = ui.registration.render()
            # Exactly this rendered RGB image goes to BOTH outputs.
            shown = image.cv2image(canvas, bgr=False, copy=True)
            trace.step("display.show", attempts - 1)
            disp.show(shown, fit=image.Fit.FIT_CONTAIN)
            del shown
            trace.step("stream.submit", attempts - 1)
            if stream is not None:
                stream.submit(canvas, now)
            finished = time.monotonic()
            frames += 1
            trace.step("frame.done", attempts - 1)
            trace.progress()
            visual_rate.update(frames, finished)
            thermal_rate.update(thermal_count, finished)
            ai_rate.update(ai_stats["completed"], finished)
            stream_rate.update(stream.encoded if stream else 0, finished)
            if finished - last_stats >= 5:
                LOG.info("V=%.1f T=%.1f AI=%.1f NET=%.1f fps; boxes=%d; AI age=%s; inference_ms=%s; replaced=%d; %s/%s",
                         visual_rate.fps, thermal_rate.fps, ai_rate.fps, stream_rate.fps,
                         len(detections), ai_stats["age"], ai_stats["inference_ms"], ai_stats["replaced"],
                         thermal_status, reader_status)
                last_stats = finished
            remaining = 1.0 / c["loop_fps"] - (finished - started) if c["loop_fps"] else 0
            if remaining > 0:
                time.sleep(remaining)
    except Exception:
        LOG.exception("Application stopped; see the error above")
        raise
    finally:
        for resource in (detector, thermal, stream, cam, disp):
            if resource is not None:
                try:
                    resource.close()
                except Exception:
                    LOG.exception("Resource cleanup failed")
        # Native display/model resources are released with their Python objects.
        detector = cam = disp = None
        trace.close()


def demo_frame(width=640, height=480, seconds=0):
    """Explicit test fixture. Never used by run_board or substituted for missing hardware."""
    yy, xx = np.indices((height, width))
    rgb = np.zeros((height, width, 3), np.uint8)
    rgb[:, :, 0] = (xx * 180 // width + 20).astype(np.uint8)
    rgb[:, :, 1] = (yy * 140 // height + 20).astype(np.uint8)
    rgb[:, :, 2] = 55
    cv2.rectangle(rgb, (width // 3, height // 4), (width * 2 // 3, height * 3 // 4), (185, 190, 200), -1)
    ty, tx = np.indices((THERMAL_H, THERMAL_W), dtype=np.float32)
    pixels = np.clip(40 + 190 * np.exp(-((tx - 80) ** 2 + (ty - 60) ** 2) / 500), 0, 254).astype(np.uint8)
    frame = {"pixels": pixels, "lo": 200, "hi": 450, "valid_temperature": True, "received_at": time.monotonic()}
    detections = [{"box": (width // 3, height // 4, width // 3, height // 2), "label": "DEMO target", "score": .94}]
    return rgb, frame, detections


def run_demo():
    import argparse
    parser = argparse.ArgumentParser(description="Synthetic fusion/RTSP test; no hardware inference")
    parser.add_argument("--demo", action="store_true")
    parser.add_argument("--host", default="127.0.0.1")
    parser.add_argument("--port", type=int, default=18554)
    parser.add_argument("--seconds", type=float, default=30)
    parser.add_argument("--snapshot", default="")
    args = parser.parse_args()
    logging.basicConfig(level=logging.INFO)
    c = dict(CONFIG)
    alignment = Alignment(c, (c["width"], c["height"]))
    ui = TouchUI(alignment)
    server = JpegRtspServer(args.host, args.port, c["stream_fps"], c["jpeg_quality"])
    print("SYNTHETIC DEMO: rtsp://%s:%d/live" % (args.host, server.port), flush=True)
    start = time.monotonic()
    saved = False
    try:
        while time.monotonic() - start < args.seconds:
            rgb, frame, detections = demo_frame(c["width"], c["height"], time.monotonic() - start)
            now = time.monotonic()
            canvas, _, _ = compose(rgb, detections, frame, alignment, now, now)
            ui.draw(canvas, "SYNTHETIC DEMO | no real camera, YOLO or temperatures")
            draw_text_rgb(canvas, "SYNTHETIC TEST", 350, 88, (255, 255, 255), .65)
            server.submit(canvas, now)
            if args.snapshot and not saved:
                if not cv2.imwrite(args.snapshot, cv2.cvtColor(canvas, cv2.COLOR_RGB2BGR)):
                    raise RuntimeError("Could not write demo snapshot")
                saved = True
            time.sleep(1.0 / (c["loop_fps"] or 30))
    finally:
        server.close()


"""Appended to the fusion bundle by build_hardware_probe.py; not a standalone module."""

def run_hardware_probe():
    import platform
    import traceback
    import maix
    from maix import app, camera, display, image, nn
    from maix import sys as maix_sys
    from maix.peripheral import uart

    logging.basicConfig(level=logging.INFO)
    report = {"test": "MaixCAM2 actual hardware probe", "synthetic": False,
              "python": platform.python_version(),
              "maixpy": getattr(maix, "__version__", "unknown"),
              "board": maix_sys.device_name(), "checks": {}, "errors": [],
              "frames": 0, "detections": 0, "inferences": 0,
              "thermal_updates": 0, "valid_temperature_frames": 0,
              "rtsp_client_seen": False, "rtsp_decode_verified": False}
    def emit(event, **details):
        print("MAIX_PROBE " + json.dumps(dict(event=event, **details)), flush=True)
    def failure(stage, exc):
        report["checks"][stage] = "FAIL"
        report["errors"].append({"stage": stage, "error": str(exc)})
        emit("ERROR", stage=stage, error=str(exc))
        traceback.print_exc()

    cam = disp = detector = reader = server = None
    start = time.monotonic()
    try:
        emit("ENVIRONMENT", board=report["board"], python=report["python"],
             maixpy=report["maixpy"], numpy=np.__version__, opencv=cv2.__version__,
             uart_devices=list(uart.list_devices()))
        if report["board"] != "MaixCAM2":
            raise RuntimeError("Wrong board: expected MaixCAM2; GPIO/UART test not started")
        report["checks"]["environment"] = "PASS"
        c = dict(CONFIG)
        validate_config(c)
        iw, ih, fmt = 640, 480, image.Format.FMT_RGB888
        try:
            path, kind = select_model(c)
            emit("MODEL_LOADING", path=path, kind=kind)
            detector = getattr(nn, kind)(model=path, dual_buff=False)
            iw, ih, fmt = detector.input_width(), detector.input_height(), detector.input_format()
            report["model"] = path
            report["checks"]["model_load"] = "PASS"
        except Exception as exc:
            failure("model_load", exc)

        cam = camera.Camera(iw, ih, fmt, fps=c["camera_fps"])
        report["checks"]["camera_open"] = "PASS"
        try:
            disp = display.Display()
        except Exception as exc:
            failure("display_open", exc)
        alignment = Alignment(c, (iw, ih), c.get("alignment_path"))
        ui = TouchUI(alignment)
        reader = ThermalReader(c)
        reader.start()
        try:
            server = JpegRtspServer(c["rtsp_host"], c["rtsp_port"], c["stream_fps"],
                                    c["jpeg_quality"], c["max_clients"])
            report["checks"]["rtsp_listen"] = "PASS"
            emit("RTSP_READY", urls=rtsp_addresses(server.port), duration_seconds=90)
        except Exception as exc:
            failure("rtsp_listen", exc)

        preview_start = last_log = time.monotonic()
        while not app.need_exit() and time.monotonic() - preview_start < 90:
            frame_start = time.monotonic()
            frame = cam.read()
            visible_at = time.monotonic()
            if frame is None:
                time.sleep(.01)
                continue
            thermal, status, count = reader.snapshot()
            detections = []
            if detector is not None:
                try:
                    objects = detector.detect(frame, conf_th=c["confidence"], iou_th=c["iou"])
                    report["inferences"] += 1
                    report["detections"] += len(objects)
                    for obj in sorted(objects, key=lambda item: item.score, reverse=True)[:c["max_objects"]]:
                        label = str(detector.labels[obj.class_id]).encode("ascii", "replace").decode("ascii")
                        detections.append({"box": (obj.x, obj.y, obj.w, obj.h),
                                           "score": obj.score, "label": label})
                except Exception as exc:
                    failure("inference", exc)
                    detector = None
            rgb = cv2.cvtColor(image.image2cv(frame, ensure_bgr=True, copy=False), cv2.COLOR_BGR2RGB)
            now = time.monotonic()
            canvas, _, thermal_status = compose(rgb, detections, thermal, alignment, now, visible_at)
            ui.draw(canvas, "HARDWARE PROBE | %ds left | %s" %
                    (max(0, int(90 - (now - preview_start))), status))
            if disp is not None:
                disp.show(image.cv2image(canvas, bgr=False, copy=True), fit=image.Fit.FIT_CONTAIN)
                report["checks"]["display_show_call"] = "PASS"
            if server is not None:
                server.submit(canvas, now)
                report["rtsp_client_seen"] |= server.client_count() > 0
                if server.error:
                    report["rtsp_error"] = str(server.error)
            report["frames"] += 1
            report["thermal_updates"] = count
            report["thermal_status"] = thermal_status
            if thermal is not None and thermal["valid_temperature"]:
                report["valid_temperature_frames"] += 1
                report["last_thermal"] = {"lo_c": thermal["lo"] / 10,
                                          "hi_c": thermal["hi"] / 10,
                                          "age_seconds": round(now - thermal["received_at"], 3)}
            if now - last_log >= 5:
                emit("PROGRESS", frames=report["frames"], inferences=report["inferences"],
                     detections=report["detections"], thermal_updates=count,
                     thermal_status=thermal_status, reader_status=status,
                     fps=round(report["frames"] / (now - preview_start), 2),
                     rtsp_clients=server.client_count() if server else 0)
                last_log = now
            if c["loop_fps"]:
                time.sleep(max(0, 1 / c["loop_fps"] - (time.monotonic() - frame_start)))
        report["checks"]["camera_frames"] = "PASS" if report["frames"] else "FAIL"
        report["checks"]["inference"] = report["checks"].get("inference", "PASS" if report["inferences"] else "NOT_RUN")
        report["checks"]["thermal_frames"] = "PASS" if report["thermal_updates"] else "FAIL"
        report["checks"]["thermal_temperature_data"] = "PASS" if report["valid_temperature_frames"] else "FAIL"
    except Exception as exc:
        failure("hardware_probe", exc)
    finally:
        for resource in (reader, server, cam, disp):
            if resource is not None:
                try:
                    resource.close()
                except Exception as exc:
                    failure("cleanup_" + type(resource).__name__, exc)
        report["elapsed_seconds"] = round(time.monotonic() - start, 2)
        report["note"] = "Temperature validity is not calibration accuracy; display.show is not visual confirmation; RTSP requires external decode verification."
        emit("RESULT", report=report)


if __name__ == "__main__":
    run_hardware_probe()
